static clj_value clojure_core_loop(void *ctx, const clj_value *args, size_t n) {
	const clj_fn *f = ctx;
	switch (n) {
	default: break;
	}
	if (n >= 3) return clojure_core_loop_v3(clj_from_ptr((void *)f), f->env, args, n);
	return clj_c_arity_error(clj_from_ptr((void *)f), n);
}

